let first = base
| summarize first_seen = min(timestamp) by user_Id;
base
| join kind=inner first on user_Id
| extend day = bin(timestamp, 1d), is_new = bin(first_seen, 1d) == bin(timestamp, 1d)
| summarize new_visitors = dcountif(user_Id, is_new), returning = dcountif(user_Id, not(is_new)) by day
| order by day asc

